cd /app/categorizationapp && python3 - <<'EOF'
import re, os, glob, importlib.util, sys
sys.path.insert(0,'.')
consts={}
for m in ['categorizationapp/UtilityScripts/BankRegexConstants.py','categorizationapp/UtilityScripts/RegexConstants.py']:
    g={}
    exec(open(m).read(), g)
    consts.update({k:v for k,v in g.items() if isinstance(v,str) and not k.startswith('__')})

call=re.compile(r'py_extract\(([^()]*(?:\([^()]*\)[^()]*)*)\)')
for f in sorted(glob.glob('categorizationapp/BankScripts/*.py')):
    src=open(f).read().split('\n')
    for i,line in enumerate(src,1):
        for m in call.finditer(line):
            args=m.group(1)
            im=re.search(r'index\s*=\s*(\d+)',args)
            if not im: continue
            idx=int(im.group(1))
            pm=re.search(r'pat\s*=\s*(.+?),\s*index',args) or re.search(r',\s*([A-Z_0-9]+)\s*,\s*index',args)
            if not pm: continue
            pat=pm.group(1).strip()
            if pat in consts: patv=consts[pat]
            elif pat.startswith(('"',"'")):
                try: patv=eval(pat)
                except: continue
            else: continue
            try: ng=re.compile(patv).groups
            except Exception as e: 
                print('BADRE',f,i,pat); continue
            if idx>=ng or ng>1:
                print(f"{os.path.basename(f)}:{i} idx={idx} groups={ng} {pat} = {patv[:70]!r}")
EOF

